#!/usr/bin/env bash
# Rocketify - Linux installer (Steam/Proton and Heroic).
# The mod loader files are embedded at the end of this script.
# (This file is the template: build.sh appends the files to make build/rocketify-install.sh.)
#
#   ./rocketify-install.sh                 interactive install
#   ./rocketify-install.sh --dir PATH      install into PATH (game root or Binaries/Win64)
#   ./rocketify-install.sh --uninstall     remove the mods (asks which install)
#   ./rocketify-install.sh --yes           don't ask, use the first install found
set -euo pipefail

VERSION="0.0.2-alpha"
B=$'\e[1m'; G=$'\e[32m'; Y=$'\e[33m'; R=$'\e[31m'; C=$'\e[36m'; N=$'\e[0m'
[ -t 1 ] || { B=""; G=""; Y=""; R=""; C=""; N=""; }

say()  { printf '%s\n' "$*"; }
ok()   { printf '%s✔%s %s\n' "$G" "$N" "$*"; }
warn() { printf '%s!%s %s\n' "$Y" "$N" "$*"; }
die()  { printf '%s✘%s %s\n' "$R" "$N" "$*" >&2; exit 1; }

# Answers come from the keyboard, even when the script itself is piped in (curl ... | bash).
if [ -t 0 ]; then TTY=/dev/stdin
elif (: </dev/tty) 2>/dev/null; then TTY=/dev/tty
else TTY=""; fi
ask() {  # ask "prompt" VARIABLE
  [ -n "$TTY" ] || die "No terminal to ask on - run again with --yes (and --dir PATH)."
  read -r -p "$1" "$2" <"$TTY"
}

# Run as "curl ... | bash"? Then this script is on stdin and cannot read the files embedded
# in itself. Download a copy to a temporary file and run that instead.
SELF_URL="${ROCKETIFY_URL:-https://raw.githubusercontent.com/ProPlat28/Rocketify/refs/heads/main/installer/rocketify-install.sh}"
if ! grep -q '^__PAYLOAD_BELOW__$' "$0" 2>/dev/null; then
  command -v curl >/dev/null 2>&1 || die "curl is needed to run this installer from a pipe."
  SELF="$(mktemp)"
  curl -fsSL "$SELF_URL" -o "$SELF" || { rm -f "$SELF"; die "Could not download the installer from $SELF_URL"; }
  rc=0
  if [ -n "$TTY" ]; then bash "$SELF" "$@" <"$TTY" || rc=$?; else bash "$SELF" "$@" </dev/null || rc=$?; fi
  rm -f "$SELF"
  exit $rc
fi

MODE=install DIR="" ASSUME_YES=0
while [ $# -gt 0 ]; do
  case "$1" in
    --dir) DIR="${2:-}"; shift 2 ;;
    --uninstall) MODE=uninstall; shift ;;
    --yes|-y) ASSUME_YES=1; shift ;;
    -h|--help) sed -n '2,9p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) die "unknown option: $1 (see --help)" ;;
  esac
done

# Normalise a path to Binaries/Win64; prints nothing if it isn't Rocket League.
win64_of() {
  local p="${1%/}"
  if [ -f "$p/RocketLeague.exe" ]; then printf '%s\n' "$p"
  elif [ -f "$p/Binaries/Win64/RocketLeague.exe" ]; then printf '%s\n' "$p/Binaries/Win64"
  fi
}

# ---------------------------------------------------------------- detection
declare -a FOUND=() KIND=() IDS=()
add_found() {  # $1 = path, $2 = kind (Steam / Heroic / Custom)
  local w; w="$(win64_of "$1")"; [ -n "$w" ] || return 0
  w="$(cd "$w" && pwd -P)"
  # same game reached through different paths (e.g. /home -> /var/home): compare the file itself
  local id; id="$(stat -L -c '%d:%i' "$w/RocketLeague.exe" 2>/dev/null || echo "$w")"
  local i; for i in "${IDS[@]+"${IDS[@]}"}"; do [ "$i" = "$id" ] && return 0; done
  FOUND+=("$w"); KIND+=("$2"); IDS+=("$id")
}

detect_steam() {
  local root vdf lib
  for root in "$HOME/.local/share/Steam" "$HOME/.steam/steam" "$HOME/.steam/root" \
              "$HOME/.var/app/com.valvesoftware.Steam/.local/share/Steam"; do
    [ -d "$root" ] || continue
    add_found "$root/steamapps/common/rocketleague" Steam
    vdf="$root/steamapps/libraryfolders.vdf"
    [ -f "$vdf" ] || continue
    while IFS= read -r lib; do
      add_found "$lib/steamapps/common/rocketleague" Steam
    done < <(sed -n 's/^[[:space:]]*"path"[[:space:]]*"\(.*\)".*/\1/p' "$vdf")
  done
}

detect_heroic() {
  local cfg path
  for cfg in "$HOME/.config/heroic/legendaryConfig/legendary/installed.json" \
             "$HOME/.var/app/com.heroicgameslauncher.hgl/config/heroic/legendaryConfig/legendary/installed.json"; do
    [ -f "$cfg" ] || continue
    while IFS= read -r path; do
      case "$path" in *[Rr]ocket[Ll]eague*|*rocketleague*) add_found "$path" Heroic ;; esac
    done < <(sed -n 's/.*"install_path"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$cfg")
  done
  add_found "$HOME/Games/Heroic/rocketleague" Heroic
}

choose_install() {
  if [ -n "$DIR" ]; then
    local w; w="$(win64_of "$DIR")"
    [ -n "$w" ] || die "No Rocket League in '$DIR' (need Binaries/Win64/RocketLeague.exe)."
    TARGET="$(cd "$w" && pwd -P)"
    case "$TARGET" in */steamapps/*) TKIND=Steam ;; *) TKIND=Custom ;; esac
    return
  fi
  detect_steam
  detect_heroic
  if [ ${#FOUND[@]} -eq 0 ]; then
    [ $ASSUME_YES -eq 1 ] && die "Rocket League not found. Use --dir PATH."
    warn "Rocket League was not found automatically."
    ask "Path to your Rocket League folder: " DIR
    DIR="${DIR/#\~/$HOME}"
    choose_install
    return
  fi
  if [ ${#FOUND[@]} -eq 1 ] || [ $ASSUME_YES -eq 1 ]; then
    TARGET="${FOUND[0]}"; TKIND="${KIND[0]}"
  else
    say "${B}Rocket League installs found:${N}"
    local i; for i in "${!FOUND[@]}"; do printf '  %s%d)%s %-7s %s\n' "$C" $((i+1)) "$N" "${KIND[$i]}" "${FOUND[$i]}"; done
    local pick
    ask "Choose [1-${#FOUND[@]}]: " pick
    [[ "$pick" =~ ^[0-9]+$ ]] && [ "$pick" -ge 1 ] && [ "$pick" -le ${#FOUND[@]} ] || die "Invalid choice."
    TARGET="${FOUND[$((pick-1))]}"; TKIND="${KIND[$((pick-1))]}"
  fi
}

confirm() {
  [ $ASSUME_YES -eq 1 ] && return 0
  local a; ask "$1 [Y/n] " a
  [[ -z "$a" || "$a" =~ ^[Yy] ]]
}

copy_to_clipboard() {
  if command -v wl-copy >/dev/null 2>&1 && [ -n "${WAYLAND_DISPLAY:-}" ]; then printf '%s' "$1" | wl-copy && return 0; fi
  if command -v xclip >/dev/null 2>&1 && [ -n "${DISPLAY:-}" ]; then printf '%s' "$1" | xclip -selection clipboard && return 0; fi
  return 1
}

# ---------------------------------------------------------------- install / uninstall
do_install() {
  tmp="$(mktemp -d)"
  trap 'rm -rf "${tmp:-}"' EXIT
  sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$tmp" \
    || die "The embedded files are damaged - download the installer again."
  mkdir -p "$TARGET/rocketify/mods"
  # Migrate an install made under the old names (RLModLauncher.exe / rlml/)
  if [ -d "$TARGET/rlml" ] || [ -f "$TARGET/RLModLauncher.exe" ]; then
    find "$TARGET/rlml/mods" -maxdepth 1 -name '*.dll' ! -name hello_mod.dll -exec mv -n {} "$TARGET/rocketify/mods/" \; 2>/dev/null || true
    rm -rf "$TARGET/rlml"
    rm -f "$TARGET/RLModLauncher.exe"
    ok "Removed the old RL Mod Loader files (your own mods were moved to rocketify/mods)"
    warn "Update your Steam Launch Options / Heroic setting: the launcher is now Rocketify.exe"
  fi
  install -m 644 "$tmp/Rocketify.exe" "$TARGET/Rocketify.exe"
  install -m 644 "$tmp/rocketify/rocketify.dll" "$TARGET/rocketify/rocketify.dll"
  install -m 644 "$tmp/rocketify/mods/hello_mod.dll" "$TARGET/rocketify/mods/hello_mod.dll"
  ok "Installed into $TARGET"
}

do_uninstall() {
  rm -f "$TARGET/Rocketify.exe" "$TARGET/rocketify/rocketify.dll" "$TARGET/rocketify/mods/hello_mod.dll" \
        "$TARGET/rocketify/rocketify.log" "$TARGET/rocketify/rocketify.ini" "$TARGET/rocketify/splash_trace.log" "$TARGET/rocketify/splash_curve.txt"
  rmdir "$TARGET/rocketify/mods" 2>/dev/null || warn "Kept your own mods in $TARGET/rocketify/mods"
  rmdir "$TARGET/rocketify" 2>/dev/null || true
  ok "Mods removed from $TARGET"
}

next_steps() {
  say ""
  if [ "$TKIND" = Steam ]; then
    local opt="bash -c 'exec \"\${@/RocketLeague.exe/Rocketify.exe}\"' -- %command%"
    say "${B}Don't forget:${N} add this to Rocket League's Launch Options in Steam"
    say "(Library > right-click Rocket League > Properties > General > Launch Options):"
    say ""
    say "  ${C}${opt}${N}"
    say ""
    if copy_to_clipboard "$opt"; then ok "Copied to your clipboard."; fi
    say "Then press Play. Clear that field again to play online with Easy Anti-Cheat."
  elif [ "$TKIND" = Heroic ]; then
    say "${B}Don't forget:${N} in Heroic, open Rocket League > Settings > Advanced and set"
    say "  Alternative executable: ${C}$TARGET/Rocketify.exe${N}"
    say "Clear it again to play online with Easy Anti-Cheat."
  else
    say "Start the game through ${C}$TARGET/Rocketify.exe${N} (with Proton/Wine) to load the mods."
  fi
  say ""
  say "Modded sessions run without Easy Anti-Cheat - use them for offline modes."
}

# ---------------------------------------------------------------- main
say "${B}Rocketify ${VERSION} - Linux installer${N}"
say "Unofficial fan-made tool, not affiliated with Psyonix or Epic Games."
say ""
choose_install
say "Rocket League ($TKIND): ${C}$TARGET${N}"

if [ "$MODE" = uninstall ]; then
  [ -f "$TARGET/Rocketify.exe" ] || die "The mods are not installed there."
  confirm "Remove the mods from this install?" || exit 0
  do_uninstall
  say "Remember to clear the Launch Options / Alternative executable you set for the mods."
  exit 0
fi

if [ -f "$TARGET/Rocketify.exe" ]; then
  confirm "The mods are already installed here. Update them?" || exit 0
else
  confirm "Install the mods here?" || exit 0
fi
do_install
next_steps
exit 0
